#include <iostream>
using namespace std;

int main() {
    int a = 3, b = 4;
    char op = '*';
    int result = 0;
    switch (op) {
        case '+': result = a + b; break;
        case '-': result = a - b; break;
        case '*': result = a * b; break;
        default: result = a / b;
    }
    cout << result << endl;
    return 0;
}

